using Commerce;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU-1", 9.99m, 1);

        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-1", 5.00m, 3);

        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDifferentItems_SumsAll()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 7.50m, 2);

        Assert.AreEqual(25.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothEntriesCounted()
    {
        _cart.AddItem("SKU-1", 5.00m, 1);
        _cart.AddItem("SKU-1", 5.00m, 2);

        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-1", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_RemovesFromTotal()
    {
        _cart.AddItem("SKU-1", 10.00m, 1);
        _cart.AddItem("SKU-2", 5.00m, 1);

        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAllEntries()
    {
        _cart.AddItem("SKU-1", 5.00m, 1);
        _cart.AddItem("SKU-1", 3.00m, 2);

        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    [DataRow(0.01, 1, 0.01)]
    [DataRow(99.99, 10, 999.90)]
    public void GetTotal_VariousPricesAndQuantities_CalculatesCorrectly(
        double price, int qty, double expected)
    {
        _cart.AddItem("X", (decimal)price, qty);

        Assert.AreEqual((decimal)expected, _cart.GetTotal());
    }
}

